insert into announcement (id, school_id, title, body, audience_type, audience_ref, author_id, published_at, pinned) values
  ('6a6f766c-c977-4582-a458-0fd54c9cdfe9', '9841acf4-fa6a-4206-a676-d54d7f81086d', '{"sq":"Takimi me prindër — 18 shtator","en":"Parent meeting — 18 September"}'::jsonb, '{"sq":"Të nderuar prindër, takimi i parë i vitit shkollor do të mbahet të enjten, më 18 shtator, nga ora 17:00 deri në 19:00. Mësuesit kujdestarë do t''ju presin në klasat përkatëse.","en":"Dear parents, the first meeting of the school year takes place on Thursday 18 September, 5pm to 7pm. Homeroom teachers will meet you in their classrooms."}'::jsonb, 'school', null, '767bd0a0-a20f-4cc3-a84c-a91927e4f6a8', '2026-09-08T14:44:24.689Z', true),
  ('6b6f7800-e877-466e-a558-01b96d9c8c05', '9841acf4-fa6a-4206-a676-d54d7f81086d', '{"sq":"Java e leximit fillon të hënën","en":"Reading week starts on Monday"}'::jsonb, '{"sq":"Gjatë javës së leximit çdo nxënës sjell një libër nga shtëpia. Në fund të javës do të kemi një orë të përbashkët leximi me prindër të ftuar.","en":"During reading week every pupil brings a book from home. At the end of the week we hold a shared reading hour with parents invited."}'::jsonb, 'school', null, '767bd0a0-a20f-4cc3-a84c-a91927e4f6a8', '2026-09-05T14:44:24.689Z', false),
  ('6c6f7990-0777-46de-a258-0029829cbcb5', '9841acf4-fa6a-4206-a676-d54d7f81086d', '{"sq":"Kopshti: veshje për oborr","en":"Kindergarten: outdoor clothing"}'::jsonb, '{"sq":"Meqë moti është ftohur, ju lutemi sillni një xhaketë shtesë dhe një palë çorape rezervë në çantën e fëmijës.","en":"As the weather has turned colder, please pack an extra jacket and a spare pair of socks in your child''s bag."}'::jsonb, 'class', 'd1c128c8-31d2-41b2-aff6-5171b439dbd9', '767bd0a0-a20f-4cc3-a84c-a91927e4f6a8', '2026-09-09T14:44:24.689Z', false)
